{
  "ParentPolicyName": "Karnataka Electronics System Design & Manufacturing Policy 2017-2022",
  "PolicyInformation": [
    {
      "PolicyName": "Operational Guidelines for Karnataka Electronics System Design & Manufacturing Policy 2017-2022",
      "Category": "Operational Guidelines",
      "Industry": "Electronics System Design & Manufacturing (ESDM)",
      "SubIndustry": "Telecom Systems, Mobiles, IT Systems and Hardware, Consumer Electronics, Medical Electronics, Avionics, Industrial Electronics, Defence & Strategic Electronics, Automotive Electronics, Information & Broadcasting Equipment, PCBs, semiconductors, chip components, ICs, Electronics Manufacturing Services (EMS), Design/IP/Software services for electronics",
      "BusinessSize": "Startup, MSME, Large Enterprise, Mega Enterprise",
      "Geography": "Karnataka",
      "Year": [
        "2017-2022"
      ],
      "SpecialAttributes": [
        "Ecosystem Support",
        "Financial Incentives"
      ],
      "Keywords": [
        "ESDM",
        "Karnataka",
        "Electronics Manufacturing",
        "Incentives",
        "Subsidy",
        "R&D Grant",
        "Capital Subsidy",
        "Patent Incentive"
      ],
      "PolicySummary": "These are the operational guidelines for the Karnataka Electronics System Design & Manufacturing (ESDM) Policy 2017-2022, issued by the Department of Information Technology, Biotechnology and Science & Technology, Government of Karnataka. The guidelines aim to support the electronics ecosystem in the state by administering a range of incentives and concessions for ESDM companies. It details the definitions, eligibility criteria, application processes, and procedures for claiming benefits. The document covers 13 different incentives, including support for patent registration, R&D, capital investment, marketing, quality certifications, and operational costs, with specific applicability for different company sizes (Startups, MSMEs, Large, and Mega Enterprises).",
      "EligibilityCriteria": "To avail financial support, a company must be registered with DIT/KBITS as a KESDM company. The company must be engaged in the manufacturing or design of electronics products, manufacturing of intermediates (like PCBs, semiconductors), or provide Electronics Manufacturing Services (EMS), design, IP, or software services for electronic products. The entity must be registered in Karnataka under the Karnataka Shops and Commercial Establishment Act, 1961, and employ at least 50% of its total workforce (excluding contract employees) in the state. A key requirement is meeting a minimum percentage of value addition within Karnataka, which increases annually from 25% in the first year to 45% in the fifth year. For companies with multiple offices, 60% of the workforce must reside in Karnataka.",
      "IncentivesAndBenefits": [
        {
          "IncentiveName": "Patent Registration Incentive",
          "Description": "Reimbursement of actual costs incurred for filing domestic and international patents for technology-based products or services.",
          "Benefits": {
            "Domestic Patent": "Up to a maximum of INR 2 Lac per patent.",
            "International Patent": "Up to a maximum of INR 10 Lacs per patent.",
            "Reimbursement Structure": "Up to 75% of the eligible expense is reimbursed upon filing, with the remaining 25% paid after the patent is granted. Alternatively, 100% can be claimed after the grant.",
            "Maximum Claims": "A single company is eligible for a maximum of five reimbursements (inclusive of domestic or international patents) during the policy period.",
            "Applicability": "Applicable to Startups, MSMEs, Large, and Mega Enterprises."
          }
        },
        {
          "IncentiveName": "International Marketing Incentive",
          "Description": "Reimbursement of costs associated with export promotion and building brand equity in international markets.",
          "Benefits": {
            "Reimbursement Rate": "50% of the actual cost incurred for registration, economy class travel, boarding, lodging, and exhibition stall rentals.",
            "Maximum Limit": "Up to INR 5 Lacs per company per year.",
            "Travel Cap": "Reimbursement is capped at 2 employees for participation in up to 2 international events per year.",
            "Daily Allowance": "Up to $100 a day for international travel (excluding journey days).",
            "Applicability": "Applicable to Startups, MSMEs, Large, and Mega Enterprises."
          }
        },
        {
          "IncentiveName": "R&D Grant",
          "Description": "Reimbursement of expenses incurred on R&D for products by registered KESDM companies that are less than 7 years old.",
          "Benefits": {
            "Grant for Startups and MSME": "25% of eligible expenses.",
            "Grant for Large and Mega Enterprises": "10% of eligible expenses.",
            "Maximum Limit": "Up to INR 2 Crores per company per year.",
            "Claim Frequency": "A single company can claim this incentive only twice during the entire policy period.",
            "Applicability": "Applicable to Startups, MSMEs, Large, and Mega Enterprises."
          }
        },
        {
          "IncentiveName": "Capital Subsidy",
          "Description": "A capital subsidy provided to the first two anchor units in each Greenfield electronics manufacturing cluster.",
          "Benefits": {
            "Subsidy Rate": "Up to 10% of the investment in fixed assets.",
            "Maximum Limit": "Up to INR 10 Crores.",
            "Applicability": "Applicable only to Large and Mega Enterprises. Not applicable to Startups and MSMEs."
          }
        },
        {
          "IncentiveName": "Reimbursement of Quality Certification Costs",
          "Description": "Reimbursement for charges incurred for getting products tested and certified from domestic or international labs (e.g., CE, ISO, CMM).",
          "Benefits": {
            "Reimbursement Rate": "Up to 50% of testing/certification charges.",
            "Maximum Limit": "Up to INR 10 Lacs per year.",
            "Applicability": "Applicable only to Startups and MSMEs."
          }
        },
        {
          "IncentiveName": "Reimbursement of Prototyping Costs",
          "Description": "Reimbursement for the costs incurred in developing a product prototype.",
          "Benefits": {
            "Reimbursement Rate": "50% of the cost incurred.",
            "Maximum Limit": "Up to INR 10 Lacs per year.",
            "Claim Frequency": "Maximum of 2 sanctions per year per company.",
            "Applicability": "Applicable only to Startups and MSMEs."
          }
        },
        {
          "IncentiveName": "Interest Subsidy",
          "Description": "Subsidy on the interest paid for term loans taken from scheduled banks or state-level financial institutions.",
          "Benefits": {
            "Subsidy Rate": "Up to 6% per annum or the effective rate of interest (whichever is lower).",
            "Loan Amount": "Applicable for loans up to INR 50 Lacs.",
            "Duration": "For a period of five years.",
            "Applicability": "Applicable only to Startups and MSMEs."
          }
        },
        {
          "IncentiveName": "PF/ESI Incentive",
          "Description": "Reimbursement of the employer's contribution towards Provident Fund (PF) and Employee's State Insurance (ESI) for new employment created during the policy period. This applies to new companies registered within the last two years.",
          "Benefits": {
            "Reimbursement Amount": "INR 2,000 per employee per month, or the actual contribution if it is less than INR 2,000.",
            "Duration": "For a continuous period of two years.",
            "Total Limit": "Up to a total reimbursement of INR 12 Lacs per company.",
            "Applicability": "Applicable only to Startups and MSMEs."
          }
        },
        {
          "IncentiveName": "Exemption from Payment of Stamp Duty and Concessional Registration Charges",
          "Description": "Exemption from stamp duty and concessional rates on registration charges for loan agreements, lease deeds, and sale deeds.",
          "Benefits": {
            "Stamp Duty Exemption (Startups and MSMEs)": "100% exemption.",
            "Stamp Duty Exemption (Large and Mega Enterprises)": "75% exemption.",
            "Concessional Registration Charges": "A concessional rate of INR 1 per INR 1000 is applicable for all companies.",
            "Applicability": "Applicable to Startups, MSMEs, Large, and Mega Enterprises."
          }
        },
        {
          "IncentiveName": "Reimbursement of Land Conversion Fee",
          "Description": "Reimbursement of the fee paid for converting land from agricultural use to industrial use.",
          "Benefits": {
            "Reimbursement Rate (Startups and MSMEs)": "75% of the fee paid.",
            "Reimbursement Rate (Large and Mega Enterprises)": "50% of the fee paid.",
            "Applicability": "Applicable to Startups, MSMEs, Large, and Mega Enterprises."
          }
        },
        {
          "IncentiveName": "Power Tariff Concession",
          "Description": "Applicability of industrial power tariff instead of the higher commercial power tariff for registered KESDM companies.",
          "Benefits": {
            "Concession": "Eligible companies will be charged industrial power tariff as per KERC regulations.",
            "Applicability": "Applicable to all registered KESDM companies (Startups, MSMEs, Large, and Mega Enterprises) setting up in Karnataka."
          }
        },
        {
          "IncentiveName": "Subsidy for Setting up ETP (Effluent Treatment Plant)",
          "Description": "A one-time capital subsidy for the establishment of an Effluent Treatment Plant (ETP).",
          "Benefits": {
            "Subsidy Rate": "Up to 50% of the cost of the ETP.",
            "Maximum Limit (Startups and MSMEs)": "Up to INR 50 Lacs.",
            "Maximum Limit (Large and Mega Enterprises)": "Up to INR 1 Crore.",
            "Applicability": "Applicable to Startups, MSMEs, Large, and Mega Enterprises."
          }
        }
      ]
    }
  ],
  "PolicyGoals": [
    "To provide ecosystem support and administer incentives/concessions to ESDM companies in Karnataka.",
    "To promote R&D and innovation in the ESDM sector through financial grants.",
    "To encourage the creation and protection of intellectual property by incentivizing patent registration.",
    "To attract large-scale investments in Greenfield electronics manufacturing clusters with capital subsidies.",
    "To foster the growth of Startups and MSMEs with targeted incentives for prototyping, quality certification, interest on loans, and employment contributions.",
    "To enhance the global competitiveness of Karnataka's ESDM industry by supporting international marketing efforts.",
    "To lower market entry barriers and operational costs through exemptions on stamp duty, land conversion fees, and power tariff concessions.",
    "To promote environmentally sustainable manufacturing by subsidizing the setup of Effluent Treatment Plants (ETP)."
  ]
}
